//! Jobs: internal units of engine work.
//!
//! This module enqueues and completes Jobs so a transition can do both in its transaction
//! (ADR-0010). Claims, Leases and retries build on the same rows.

use std::fmt;

use chrono::{DateTime, Utc};
use serde_json::Value;
use sqlx::PgConnection;
use uuid::Uuid;

use crate::StoreError;
use crate::runs::RunId;

/// A Job's id, generated by the store.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct JobId(i64);

impl JobId {
    pub fn get(self) -> i64 {
        self.0
    }
}

impl fmt::Display for JobId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

/// What a Job does.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum JobKind {
    /// Advance a Run from its Checkpoint.
    AdvanceRun,
}

impl JobKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::AdvanceRun => "advance_run",
        }
    }

    fn from_db(kind: &str) -> Result<Self, StoreError> {
        match kind {
            "advance_run" => Ok(Self::AdvanceRun),
            other => Err(StoreError::invalid("job kind", other)),
        }
    }
}

/// A Job to enqueue.
#[derive(Debug, Clone, PartialEq)]
pub struct NewJob {
    pub kind: JobKind,
    pub run_id: Option<RunId>,
    pub payload: Value,
    /// When the Job becomes claimable; later than now for a delayed Job.
    pub run_at: DateTime<Utc>,
}

impl NewJob {
    /// A Job that advances `run`, claimable from `run_at`.
    pub fn advance_run(run: RunId, run_at: DateTime<Utc>) -> Self {
        Self {
            kind: JobKind::AdvanceRun,
            run_id: Some(run),
            payload: Value::Object(serde_json::Map::new()),
            run_at,
        }
    }
}

/// An enqueued Job.
#[derive(Debug, Clone, PartialEq)]
pub struct Job {
    pub id: JobId,
    pub kind: JobKind,
    pub run_id: Option<RunId>,
    pub payload: Value,
    pub run_at: DateTime<Utc>,
    pub attempts: i32,
    pub locked_by: Option<String>,
    pub locked_until: Option<DateTime<Utc>>,
    pub last_error: Option<String>,
}

/// A `jobs` row as read back from Postgres.
struct JobRow {
    id: i64,
    kind: String,
    run_id: Option<Uuid>,
    payload: Value,
    run_at: DateTime<Utc>,
    attempts: i32,
    locked_by: Option<String>,
    locked_until: Option<DateTime<Utc>>,
    last_error: Option<String>,
}

impl TryFrom<JobRow> for Job {
    type Error = StoreError;

    fn try_from(row: JobRow) -> Result<Self, StoreError> {
        Ok(Self {
            id: JobId(row.id),
            kind: JobKind::from_db(&row.kind)?,
            run_id: row.run_id.map(RunId::from_uuid),
            payload: row.payload,
            run_at: row.run_at,
            attempts: row.attempts,
            locked_by: row.locked_by,
            locked_until: row.locked_until,
            last_error: row.last_error,
        })
    }
}

/// Enqueues a Job.
pub async fn enqueue(conn: &mut PgConnection, job: &NewJob) -> Result<JobId, StoreError> {
    let id = sqlx::query_scalar!(
        r#"
        INSERT INTO jobs (kind, run_id, payload, run_at)
        VALUES ($1, $2, $3, $4)
        RETURNING id
        "#,
        job.kind.as_str(),
        job.run_id.map(RunId::as_uuid),
        job.payload,
        job.run_at,
    )
    .fetch_one(&mut *conn)
    .await?;

    Ok(JobId(id))
}

/// Completes a Job, removing it from the table.
pub async fn complete(conn: &mut PgConnection, id: JobId) -> Result<(), StoreError> {
    let deleted = sqlx::query!("DELETE FROM jobs WHERE id = $1", id.0)
        .execute(&mut *conn)
        .await?
        .rows_affected();

    if deleted == 0 {
        return Err(StoreError::JobNotFound(id));
    }
    Ok(())
}

/// Lists the pending Jobs of a Run, oldest first.
pub async fn list_for_run(conn: &mut PgConnection, run: RunId) -> Result<Vec<Job>, StoreError> {
    let rows = sqlx::query_as!(
        JobRow,
        r#"
        SELECT id, kind, run_id, payload, run_at, attempts, locked_by, locked_until, last_error
        FROM jobs
        WHERE run_id = $1
        ORDER BY id
        "#,
        run.as_uuid(),
    )
    .fetch_all(&mut *conn)
    .await?;

    rows.into_iter().map(Job::try_from).collect()
}
